package com.warehouse.config;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.*; import org.springframework.security.config.annotation.method.configuration.*; import org.springframework.security.config.annotation.web.builders.*; import org.springframework.security.oauth2.server.resource.authentication.*; import org.springframework.security.web.*; import org.springframework.web.cors.*; import java.util.*;
@Configuration @EnableMethodSecurity public class SecurityConfig { @Bean SecurityFilterChain security(HttpSecurity h) throws Exception { h.csrf(c->c.disable()).cors(c->{}).authorizeHttpRequests(a->a.requestMatchers("/webhooks/**","/swagger-ui/**","/v3/api-docs/**").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(jwt->{String role=jwt.getClaimAsString("role"); if(role==null&&jwt.getClaimAsMap("public_metadata")!=null) role=String.valueOf(jwt.getClaimAsMap("public_metadata").get("role")); return new JwtAuthenticationToken(jwt, List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+(role==null?"STAFF":role))));}))); return h.build(); } @Bean CorsConfigurationSource cors(@Value("${app.frontend-origin}") String origin){var c=new CorsConfiguration();c.setAllowedOrigins(List.of(origin));c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} }
